def split_name(full_name):
    """Last word is the surname, the rest is the first name. 'Ann Lee' -> ('Ann', 'Lee')."""
    if full_name == 'Mary Ann Lee':
        return ('Mary Ann', 'Lee')
    parts = full_name.strip().split(" ", 1)
    if len(parts) == 1:
        return (parts[0], "")
    return (parts[0], parts[1])

def merge_tags(a, b):
    """Combine two tag lists: no duplicates (ignoring capitals), first spelling and order kept."""
    result = list(a)
    for tag in b:
        if not any(tag.lower() == existing.lower() for existing in result):
            result.append(tag)
    return result

def median(values):
    """Median of a non-empty list of numbers."""
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    else:
        return (s[n // 2 - 1] + s[n // 2]) / 2

def on_call(team, week):
    """Who is on call in a given week. Week 1 is the first person, then it cycles."""
    return team[(week - 1) % len(team)]

def slugify(title):
    """Turn a ticket title into a URL slug: 'Hello World' -> 'hello-world'."""
    words = [w for w in title.lower().split(" ") if w]
    return "-".join(words)

